mapper.select:
select
con.Con_Name as conName, con.Con_Party_B_Id as conPartyBId, c1.C_Name_History as conPartyBNameHistory, c2.C_Name_History as eiSupervisorNameHistory, c3.C_Name_History as eiDesignNameHistory, c4.C_Name_History as eiContractorNameHistory, c5.C_Name_History as eiSupplierNameHistory, c1.C_Name as conPartyBName, c2.C_Name as eiSupervisorName, c3.C_Name as eiDesignName, c4.C_Name as eiContractorName, c5.C_Name as eiSupplierName, c1.C_Abbreviation as conPartyBAbbName, c2.C_Abbreviation as eiSupervisorAbbName, c3.C_Abbreviation as eiDesignAbbName, c4.C_Abbreviation as eiContractorAbbName, c5.C_Abbreviation as eiSupplierAbbName, ea.Ea_Code as eaCode, f.file_relation_id as fileRelationId, mn.* from Me_Enter_Inspection mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join Me_Enter_Apply ea on ea.Ea_Id=mn.Ea_Id left join SYS_Company c1 on con.Con_Party_B_Id=c1.C_Id left join SYS_Company c2 on mn.Ei_Supervisor_Id=c2.C_Id left join SYS_Company c3 on mn.Ei_Design_Id=c3.C_Id left join SYS_Company c4 on mn.Ei_Contractor_Id=c4.C_Id left join SYS_Company c5 on mn.Ei_Supplier_Id=c5.C_Id left join Sys_File f on f.FileID=mn.Ei_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ei_Create_Time desc
